const softDeleteMailAccount = `-- name: SoftDeleteMailAccount :execrows
UPDATE mail_accounts
SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
    password_enc = '', refresh_token_enc = '', imap_password_enc = ''
WHERE tenant_id = ? AND id = ? AND deleted_at IS NULL
`

type SoftDeleteMailAccountParams struct {
	TenantID string
	ID       string
}

// Soft delete clears the three credential columns in the same statement.
// Credential ciphertext must not linger behind a deleted_at flag.
func (q *Queries) SoftDeleteMailAccount(ctx context.Context, arg SoftDeleteMailAccountParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteMailAccount, arg.TenantID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const softDeleteMailAccountsByTenant = `-- name: SoftDeleteMailAccountsByTenant :execrows
UPDATE mail_accounts
SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
    password_enc = '', refresh_token_enc = '', imap_password_enc = ''
WHERE tenant_id = ? AND deleted_at IS NULL
`

// Used when an admin deletes a user: wipes the whole tenant's mailboxes and
// clears the credential ciphertext in the same statement, so nothing sensitive
// lingers behind a deleted_at flag (08 doc section 6, item 6).
func (q *Queries) SoftDeleteMailAccountsByTenant(ctx context.Context, tenantID string) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteMailAccountsByTenant, tenantID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

